// Zustand 내부 동작 (개념적으로)
const store = {
  state: { count: 0 },
  listeners: new Set(),  // 구독자 목록

  // emit() 역할
  setState(newState) {
    this.state = { ...this.state, ...newState }
    this.listeners.forEach(fn => fn())  // 구독자 전부 알림
  },

  // on() 역할
  subscribe(listener) {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)  // off()
  }
}

export default store  // Singleton으로 export

